def match_shape(grid, color):
 h,w=len(grid),len(grid[0]); pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
 r0=min(r for r,c in pts); c0=min(c for r,c in pts)
 shape=[(r-r0,c-c0) for r,c in pts]; sh=max(r for r,c in shape)+1; sw=max(c for r,c in shape)+1
 out=[row[:] for row in grid]
 for i in range(h-sh+1):
  for j in range(w-sw+1):
   target=[(i+r,j+c) for r,c in shape]
   if all(grid[r][c]==0 for r,c in target):
    for r,c in target:out[r][c]=color
 return out
